{
  "title": "Finding the Cause of an Aircraft Mishap",
  "setting": "Pacific Ocean, 22 July 2012; U.S. Air Force mishap investigation concerning an F-16C assigned to Misawa Air Base, Japan.",
  "decider": "The Board president",
  "agent_recast": false,
  "recast_note": "",
  "agent": "The Board president",
  "agent_role": "decide",
  "situation": "At the end of the investigation into an F-16C loss of thrust over the Pacific, the Board president must make the causal finding. The recovered main fuel shutoff valve was fully closed, and the considered explanations included pilot command and an uncommanded electrical input. The engine ran at 70% RPM for about three minutes before the valve fully closed, then remained at about 20% RPM until impact. Technical guidance and simulator testing compared that sequence with the expected effects of pilot-commanded closure. Corrosion was observed on a valve connector, but its cause and connection to an electrical short were not established. Important fuel-system wreckage was unrecovered, and the crash-survivable data unit was crushed. The causal finding is subject to a clear-and-convincing-evidence standard.",
  "question": "What should the Board president find as the mishap's cause under the applicable evidentiary standard?",
  "facts": [
    {
      "id": "F1",
      "kind": "situation",
      "status": "confirmed",
      "fact": "On 22 July 2012, an F-16C experienced a loss of thrust, the pilot ejected without injury, and the aircraft crashed into the Pacific Ocean.",
      "spans": [
        "src:b8e242436753#p1.314"
      ]
    },
    {
      "id": "F2",
      "kind": "capability",
      "status": "confirmed",
      "fact": "The recovered main fuel shutoff valve was fully closed, and an electrical signal is required to close it in flight.",
      "spans": [
        "src:b8e242436753#p1.318"
      ]
    },
    {
      "id": "F3",
      "kind": "situation",
      "status": "assessed",
      "fact": "The engine operated at 70% RPM for over three minutes before the valve fully closed, then remained at jet-fuel-starter-assisted 20% RPM until impact.",
      "spans": [
        "src:b8e242436753#p1.313",
        "src:b8e242436753#p1.320"
      ]
    },
    {
      "id": "F4",
      "kind": "capability",
      "status": "assessed",
      "fact": "Technical guidance and simulator testing indicated that pilot-commanded closure would fully close the valve within 2–4 seconds and produce a different engine rundown sequence.",
      "spans": [
        "src:b8e242436753#p1.320"
      ]
    },
    {
      "id": "F5",
      "kind": "situation",
      "status": "assessed",
      "fact": "The F-16 had a history of partial or full uncommanded main fuel shutoff valve closures, with corrosion identified as the cause in most such cases.",
      "spans": [
        "src:b8e242436753#p1.321"
      ]
    },
    {
      "id": "F6",
      "kind": "situation",
      "status": "assessed",
      "fact": "Corrosion was observed on the recovered valve connector, and corrosion there could cause an electrical short capable of closing the valve.",
      "spans": [
        "src:b8e242436753#p1.321"
      ]
    },
    {
      "id": "F7",
      "kind": "situation",
      "status": "assessed",
      "fact": "Technical analysis could not determine whether the connector corrosion was associated with pre-crash conditions or the aircraft's two months of ocean-floor submersion.",
      "spans": [
        "src:b8e242436753#p1.322"
      ]
    },
    {
      "id": "F8",
      "kind": "situation",
      "status": "confirmed",
      "fact": "The cockpit fuel control panel, fuel control wiring harness, and other fuel-system components were not recovered, and the crash-survivable data unit was crushed.",
      "spans": [
        "src:b8e242436753#p1.313"
      ]
    },
    {
      "id": "F9",
      "kind": "authority",
      "status": "confirmed",
      "fact": "The Board president applied clear and convincing evidence to the mishap-cause finding and a preponderance of evidence to the engine's partial-closure sequence.",
      "spans": [
        "src:b8e242436753#p1.313",
        "src:b8e242436753#p1.324"
      ]
    }
  ],
  "options": {
    "O1": {
      "do": "The Board president accepts uncommanded closure as the established cause of the mishap.",
      "move": "act",
      "disposition": "accept",
      "irreversible": true
    },
    "O2": {
      "do": "The Board president rejects an uncommanded-closure finding and records the mishap cause as undetermined.",
      "move": "act",
      "disposition": "reject",
      "irreversible": true
    }
  },
  "opposite_pair": [
    "O1",
    "O2"
  ],
  "real_option": "O1",
  "authored_options": [
    "O2"
  ],
  "no_opposite_reason": ""
}

